INSERT INTO `agenda` (`kdAgenda`, `kdMember`, `judul`, `hari`, `tglS`, `tglE`, `waktu`, `tempat`, `poster`, `posterF`, `keteranganS`, `keteranganE`, `final`, `taAgenda`, `ins`) VALUES
(1, 'MFC-memb-1', 'pendataan data dasar pembangunan sebagai informasi publik', 'minggu', '2022-09-17', '2022-09-20', '23:00', 'Bappeda litbang', '', 'cv_2020_new_1-2022-09-20-01-23-14am.png/CV_BGS_MANTAP-2022-09-20-01-23-14am.jpg', 'keterangansa', '', 1, '2022', '2022-09-22 02:17:58'),
(1, 'MFC-memb-2', 'koordinasi kedinasan berdasarkan informasi dari pemprov', 'jumat', '2022-09-17', '0000-00-00', '09:00', 'bappeda', '', 'DALAM_KANAN-2022-09-20-01-33-45am.png/cd-2022-09-20-01-33-45am.jpg', 'keteranganpop', '', 1, '2022', '2022-09-22 02:17:58'),
(11, 'MFC-memb-1', 'menukil hadish', 'kamis', '2022-09-20', '0000-00-00', '11:11', 'rws', 'IMG_20191214_181813_868-2022-09-20-11-08-01am.jpg', '', 'Sumbawa Barat Dalam Angka 2022 merupakan publikasi tahunan yang&nbsp;<br />diterbitkan oleh BPS Kabupaten Sumbawa Barat. Disadari bahwa publikasi ini&nbsp;<br />belum sepenuhnya memenuhi harapan pihak pemakai data khususnya para&nbsp;<br />perencana, namun diharapkan dapat membantu melengkapi penyusunan&nbsp;<br />rencana pembangunan di Kabupaten Sumbawa Barat.<br />Publikasi ini dapat terwujud berkat kerja sama dan bantuan dari berbagai&nbsp;<br />pihak baik instansi pemerintah maupun swasta. Kepada semua pihak yang telah&nbsp;<br />memberikan bantuan disampaikan penghargaan dan terima kasih yang sebesar&nbsp;<br />&ndash;besarnya.<br />Walaupun publikasi ini telah disiapkan sebaik-baiknya, namun disadari&nbsp;<br />masih ada kekurangan dan kesalahan yang terjadi. Untuk perbaikan publikasi&nbsp;<br />ini, tanggapan dan saran yang bersifat konstruktif dari para pemakai sangat&nbsp;<br />diharapkan', 'Sumbawa Barat in Figures 2022 is an annual publication written by BPS Regency&nbsp;<br />of Sumbawa Barat. Honestly, this publication has not perfect yet and has not filled the&nbsp;<br />user&rsquo;s hope, especially for the planners yet, but hopely it can help to equip compilation&nbsp;<br />of development planning in this new regency.<br />This comprehensive publication has been made possible with the assistance and&nbsp;<br />contribution from several governmental institutions and private organizations. To all&nbsp;<br />parties who have been involved in the preparation of this publication, I would like to&nbsp;<br />express my sincerest appreciation and gratitude.<br />Comments and constructive suggestions for the improvement of this publication&nbsp;<br />are always welcome', 1, '2022', '2022-09-22 02:17:58');
